<!--
  @component
  The equivalent of the HTML `<input type="checkbox">` element.
  @see https://developer.mozilla.org/en-US/docs/Web/HTML/Element/input/checkbox
  @see https://w3c.github.io/aria/#checkbox
  @see https://www.w3.org/WAI/ARIA/apg/patterns/checkbox/
-->
<script>
  import Button from '../button/button.svelte';
  import Icon from '../icon/icon.svelte';

  /**
   * @import { Snippet } from 'svelte';
   * @import { ButtonProps, CommonEventHandlers } from '../../typedefs.js';
   */

  /**
   * @typedef {object} Props
   * @property {string} [class] The `class` attribute on the wrapper element.
   * @property {boolean} [required] Whether to mark the widget required. An alias of the
   * `aria-required` attribute.
   * @property {boolean} [invalid] Whether to mark the widget invalid. An alias of the
   * `aria-invalid` attribute.
   * @property {boolean | 'mixed'} [checked] Whether to check the widget. An alias of the
   * `aria-checked` attribute.
   * @property {string} [label] Text label displayed next to the checkbox.
   * @property {string} [ariaLabel] `aria-label` attribute.
   * @property {Snippet} [checkIcon] Check icon slot content.
   * @property {string[]} [group] The two-way bound variable to manage the state of a group of
   * checkboxes. It works in the same way as the [`<input
   * bind:group>`](https://svelte.dev/docs/svelte/bind#input-bind:group) of Svelte.
   */

  /**
   * @type {ButtonProps & CommonEventHandlers & Props & Record<string, any>}
   */
  let {
    /* eslint-disable prefer-const */
    checked = $bindable(false),
    class: className,
    name = undefined,
    value = undefined,
    hidden = false,
    disabled = false,
    readonly = false,
    required = false,
    invalid = false,
    label = undefined,
    ariaLabel = undefined,
    group = $bindable(),
    onChange,
    children,
    checkIcon,
    ...restProps
    /* eslint-enable prefer-const */
  } = $props();

  const id = $props.id();

  /**
   * Reference to the `<button>` element.
   * @type {HTMLButtonElement | undefined}
   */
  let buttonElement = $state();

  /**
   * Accessible name given as a prop or as a plain `aria-label` attribute. It takes the place of the
   * visible label, which the button otherwise points at — but only when there is one to point at.
   * @type {string | undefined}
   */
  const accessibleLabel = $derived(ariaLabel ?? restProps['aria-label']);
  const hasVisibleLabel = $derived(!!(children || label));
  const indeterminate = $derived(checked === 'mixed');

  // Sync `checked` with `group` and `value`
  $effect(() => {
    if (Array.isArray(group)) {
      if (group.includes(value)) {
        if (checked !== true) {
          checked = true;
        }
      } else if (checked !== false) {
        checked = false;
      }
    }
  });
</script>

<div
  role="none"
  class="sui checkbox {className}"
  class:checked
  class:indeterminate
  class:disabled
  class:readonly
  {hidden}
  onclick={(event) => {
    event.preventDefault();
    event.stopPropagation();

    // The button handles its own clicks, and doesn’t let them reach here
    /* v8 ignore else */
    if (!(/** @type {HTMLElement} */ (event.target).matches('button'))) {
      buttonElement?.click();
    }
  }}
>
  <div role="none" class="inner" inert={disabled}>
    <Button
      {...restProps}
      bind:element={buttonElement}
      role="checkbox"
      {id}
      {name}
      {value}
      {hidden}
      {disabled}
      {readonly}
      aria-required={required}
      aria-invalid={invalid}
      aria-checked={checked}
      aria-label={accessibleLabel || undefined}
      aria-labelledby={!accessibleLabel && hasVisibleLabel ? `${id}-label` : undefined}
      onclick={(event) => {
        event.preventDefault();
        event.stopPropagation();

        if (disabled || readonly) {
          return;
        }

        checked = indeterminate ? true : !checked;

        // The effect above keeps `checked` in step with the group, so a newly checked box is never
        // in the group already, and a newly unchecked one is never missing from it
        if (Array.isArray(group)) {
          if (checked) {
            /* v8 ignore else */
            if (!group.includes(value)) {
              group = [...group, value];
            }
          } else /* v8 ignore else */ if (group.includes(value)) {
            group = group.filter((v) => v !== value);
          }
        }

        onChange?.(new CustomEvent('Change', { detail: { checked } }));
      }}
    >
      {#snippet startIcon()}
        {#if checkIcon}
          {@render checkIcon()}
        {:else if indeterminate}
          <Icon name="remove" />
        {:else if checked}
          <Icon name="check" />
        {/if}
      {/snippet}
    </Button>
    {#if hasVisibleLabel}
      <label id="{id}-label">
        {#if children}
          {@render children()}
        {:else}
          {label}
        {/if}
      </label>
    {/if}
  </div>
</div>

<style>.checkbox {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: var(--sui-focus-ring-width);
  min-width: 24px;
  min-height: 24px;
  color: var(--sui-control-foreground-color);
  font-family: var(--sui-control-font-family);
  font-size: var(--sui-control-font-size);
  line-height: var(--sui-control-line-height);
  cursor: pointer;
  -webkit-user-select: none;
  user-select: none;
}
.checkbox:hover :global(button) {
  background-color: var(--sui-hover-background-color);
}
.checkbox:hover :global(button[aria-checked=true]) {
  background-color: var(--sui-primary-accent-color-light);
}
.checkbox:active :global(button) {
  background-color: var(--sui-active-background-color);
}
.checkbox:active :global(button[aria-checked=true]) {
  background-color: var(--sui-primary-accent-color-dark);
}
.checkbox :global(button) {
  flex: none;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  margin: 0 !important;
  border-width: var(--sui-checkbox-border-width, 1.5px);
  border-color: var(--sui-checkbox-border-color);
  border-radius: var(--sui-checkbox-border-radius);
  padding: 0;
  width: var(--sui-checkbox-height);
  height: var(--sui-checkbox-height);
  color: var(--sui-primary-accent-text-color);
  background-color: var(--sui-checkbox-background-color);
  transition: all 200ms;
}
.checkbox :global(button[aria-checked=true]) {
  border-color: var(--sui-checkbox-border-color-checked, var(--sui-primary-accent-color));
  color: var(--sui-checkbox-foreground-color-checked, var(--sui-primary-accent-color-inverted));
  background-color: var(--sui-checkbox-background-color-checked, var(--sui-primary-accent-color));
}
.checkbox :global(button[aria-invalid=true]) {
  border-color: var(--sui-error-border-color);
  color: var(--sui-error-foreground-color);
}
.checkbox :global(button[aria-checked=true][aria-invalid=true]) {
  background-color: var(--sui-checkbox-background-color);
}
.checkbox :global(button) :global(.icon) {
  font-size: calc(var(--sui-checkbox-height) - 2px);
}
.checkbox label {
  cursor: inherit;
}
.checkbox.readonly {
  cursor: default;
}
.checkbox.readonly :global(button), .checkbox.readonly:is(:hover, :active) :global(button) {
  background-color: var(--sui-checkbox-background-color);
}
.checkbox.readonly :global(button[aria-checked='true']:not([aria-invalid='true'])), .checkbox.readonly:is(:hover, :active) :global(button[aria-checked='true']:not([aria-invalid='true'])) {
  border-color: var(--sui-readonly-accent-color);
  color: var(--sui-readonly-accent-color-inverted);
  background-color: var(--sui-readonly-accent-color);
}

.inner {
  display: contents;
}</style>
