<!--
  @component
  A generic, single-line text field. The equivalent of the HTML `<input type="text">` element.
  @see https://developer.mozilla.org/en-US/docs/Web/HTML/Element/input/text
  @see https://w3c.github.io/aria/#textbox
-->
<script>
  import { activateKeyShortcuts } from '@sveltia/utils/events';
  import TruncatedText from '../typography/truncated-text.svelte';
  import EmojiAutocomplete from './emoji-autocomplete.svelte';

  /**
   * @import { CommonEventHandlers, InputEventHandlers, TextInputProps } from '../../typedefs.js';
   */

  /**
   * @typedef {object} Props
   * @property {string} [value] Input value.
   * @property {boolean} [useEmojiAutocomplete] Whether to autocomplete emojis when the user
   * types a shortcode, like `:smi`.
   */

  /**
   * @type {TextInputProps & CommonEventHandlers & InputEventHandlers & Props & Record<string, any>}
   */
  let {
    /* eslint-disable prefer-const */
    value = $bindable(),
    element = $bindable(),
    role = 'textbox',
    keyShortcuts = undefined,
    dir = undefined,
    name = undefined,
    showInlineLabel = false,
    inputmode = 'text',
    flex = false,
    monospace = false,
    debounce = false,
    useEmojiAutocomplete = false,
    class: className,
    hidden = false,
    disabled = false,
    readonly = false,
    required = false,
    invalid = false,
    ariaLabel = undefined,
    children,
    oninput,
    ...restProps
    /* eslint-enable prefer-const */
  } = $props();

  const id = $props.id();
  const timeout = $derived(typeof debounce === 'number' ? debounce : 300);
  /**
   * Accessible label, whether given as the `ariaLabel` prop or as a plain `aria-label` attribute,
   * which the wrapper components such as `<SearchBar>` and `<NumberInput>` pass through as is.
   * @type {string | undefined}
   */
  const label = $derived(ariaLabel ?? restProps['aria-label']);

  let debounceTimer = 0;

  $effect(() => () => {
    clearTimeout(debounceTimer);
  });

  /**
   * Update the `value` and call the `oninput` callback.
   * @param {InputEvent} event The `input` event object.
   */
  const fireInput = (event) => {
    value = element?.value;
    oninput?.(event);
  };

  /**
   * Handle the `input` event. If `debounce` is `true`, the event will be debounced by 300ms. We use
   * `oninputcapture` to ensure that the event is fired before any `oninput` handlers on parent
   * elements, including the Lexical editor.
   * @param {Event} event The `input` event object.
   */
  const handleInput = (event) => {
    const inputEvent = /** @type {InputEvent} */ (event);

    if (debounce) {
      clearTimeout(debounceTimer);
      debounceTimer = /** @type {number} */ (
        /** @type {unknown} */ (
          setTimeout(() => {
            fireInput(inputEvent);
          }, timeout)
        )
      );
    } else {
      fireInput(inputEvent);
    }
  };
</script>

<div
  role="none"
  class="sui text-input {className}"
  class:flex
  class:monospace
  class:disabled
  class:readonly
  {hidden}
>
  <input
    bind:this={element}
    {...restProps}
    {value}
    type="text"
    {role}
    {dir}
    {name}
    tabindex={disabled ? -1 : 0}
    disabled={disabled || undefined}
    readonly={readonly || undefined}
    {inputmode}
    aria-label={label}
    aria-hidden={hidden}
    aria-disabled={disabled}
    aria-readonly={readonly}
    aria-required={required}
    aria-invalid={invalid}
    oninputcapture={handleInput}
    {@attach activateKeyShortcuts(keyShortcuts)}
  />
  {#if useEmojiAutocomplete && !disabled && !readonly}
    <EmojiAutocomplete {element} />
  {/if}
  {#if label && showInlineLabel}
    <span id="{id}-label" class="label" class:hidden={!!value} aria-hidden="true">
      <TruncatedText>
        {label}
      </TruncatedText>
    </span>
  {/if}
</div>

<style>.text-input {
  display: inline-flex;
  align-items: center;
  position: relative;
  margin: var(--sui-focus-ring-width);
  min-width: var(--sui-textbox-singleline-min-width);
}
.text-input.flex:not([hidden]) {
  display: inline-flex;
  width: -moz-available;
  width: -webkit-fill-available;
  width: stretch;
  min-width: 0;
}
.text-input.monospace {
  --sui-textbox-font-family: var(--sui-font-family-monospace, monospace);
}

input:is(:-webkit-autofill, :-webkit-autofill:focus) {
  transition: background-color 0s 600000s, color 0s 600000s;
}

input {
  display: inline-block;
  flex: auto;
  border-width: var(--sui-textbox-border-width, 1px);
  border-color: var(--sui-textbox-border-color);
  border-radius: var(--sui-textbox-border-radius);
  padding: var(--sui-textbox-singleline-padding);
  min-width: 0;
  height: var(--sui-textbox-height);
  color: var(--sui-textbox-foreground-color);
  background-color: var(--sui-textbox-background-color);
  font-family: var(--sui-textbox-font-family);
  font-size: var(--sui-textbox-font-size);
  line-height: var(--sui-textbox-singleline-line-height);
  font-weight: var(--sui-textbox-font-weight, var(--sui-font-weight-normal, normal));
  text-align: var(--sui-textbox-text-align, start);
  text-indent: var(--sui-textbox-text-indent, 0);
  text-transform: var(--sui-textbox-text-transform, none);
  letter-spacing: var(--sui-textbox-letter-spacing, normal);
  word-spacing: var(--sui-word-spacing-normal, normal);
  transition: all 200ms;
}
input:focus {
  color: var(--sui-textbox-foreground-color-focus, var(--sui-textbox-foreground-color));
  background-color: var(--sui-textbox-background-color-focus, var(--sui-textbox-background-color));
}
input:read-only {
  color: var(--sui-secondary-foreground-color);
  border-color: var(--sui-textbox-border-color) !important;
}
input:is(:disabled, :read-only) {
  background-color: var(--sui-disabled-background-color);
}
input[aria-invalid=true] {
  border-color: var(--sui-error-border-color);
}
input ~ :global(button) {
  flex: none;
  margin-inline-start: -1px;
  border-width: 1px;
  border-color: var(--sui-textbox-border-color);
  height: var(--sui-textbox-height);
  aspect-ratio: 1/1;
}
input ~ :global(button:last-child) {
  border-start-start-radius: 0;
  border-start-end-radius: 4px;
  border-end-end-radius: 4px;
  border-end-start-radius: 0;
}
input ~ :global(button) :global(.icon) {
  font-size: var(--sui-font-size-xx-large);
}

.label {
  position: absolute;
  inset: var(--sui-textbox-singleline-padding);
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: var(--sui-textbox-placeholder-text-align, var(--sui-textbox-text-align, start));
  pointer-events: none;
}
.label.hidden {
  opacity: 0;
}

input:focus + .label {
  opacity: 0;
}

input::placeholder,
.label {
  color: var(--sui-textbox-placeholder-foreground-color, var(--sui-textbox-foreground-color));
  opacity: var(--sui-textbox-placeholder-opacity, 0.5);
  font-family: var(--sui-textbox-placeholder-font-family, var(--sui-textbox-font-family));
  font-size: var(--sui-textbox-placeholder-font-size, var(--sui-textbox-font-size));
  line-height: var(--sui-textbox-placeholder-singleline-line-height, var(--sui-textbox-singleline-line-height));
  font-weight: var(--sui-textbox-placeholder-font-weight, var(--sui-textbox-font-weight, var(--sui-font-weight-normal, normal)));
  text-align: var(--sui-textbox-placeholder-text-align, var(--sui-textbox-text-align, start));
  text-indent: var(--sui-textbox-placeholder-text-indent, var(--sui-textbox-text-indent, 0));
  letter-spacing: var(--sui-textbox-placeholder-letter-spacing, var(--sui-textbox-letter-spacing, normal));
}</style>
