import { generateElementId } from '@sveltia/utils/element';
import { convertHtmlToLexical, convertMarkdownToLexical } from './core.js';

/**
 * @import { LexicalEditor } from 'lexical';
 * @import { Transformer } from '@lexical/markdown';
 * @import { TextEditorConfig, TextEditorSelectionState, TextEditorStore } from '../../typedefs.js';
 */

/**
 * Create an editor editor store that contains all the states and configuration.
 * @returns {TextEditorStore} Store.
 */
export const createEditorStore = () => {
  /** @type {string} */
  const editorId = generateElementId('editor');
  /** @type {boolean} */
  let initialized = $state(false);
  /** @type {LexicalEditor | undefined} */
  let editor = $state();
  /** @type {Transformer[]} */
  let enabledTransformers = $state([]);

  /** @type {TextEditorConfig} */
  let config = $state({
    modes: [],
    enabledButtons: [],
    components: [],
    useMarkdownShortcuts: true,
    isCodeEditor: false,
    useEmojiAutocomplete: false,
  });

  /** @type {string} */
  let inputValue = $state('');
  /** @type {TextEditorSelectionState} */
  let selection = $state({ blockNodeKey: null, blockType: 'paragraph', inlineTypes: [] });
  /** @type {boolean} */
  let useRichText = $state(true);
  /** @type {HTMLTextAreaElement | undefined} */
  let textArea = $state();
  /** @type {boolean} */
  let hasConverterError = $state(false);
  /** @type {boolean} */
  let showConverterError = $state(false);
  /** @type {boolean} */
  let pending = $state(false);
  /**
   * Number of editor operations started by the user that have yet to update the editor.
   * @type {number}
   */
  let runningOperations = $state(0);
  /**
   * Value last imported to the Lexical editor, and the Markdown or HTML the editor exports for it.
   * @type {{ source: string, exported: string } | undefined}
   */
  let lastImport = undefined;
  /**
   * Number of imports started, to tell the latest one.
   * @type {number}
   */
  let importCount = 0;
  /**
   * Whether the latest import is still in progress.
   * @type {boolean}
   */
  let importing = false;

  /**
   * Flag a conversion error, which takes the editor out of the rich text mode, and shows the error
   * to the user.
   * @param {boolean} newValue Whether there is an error.
   */
  const setConverterError = (newValue) => {
    hasConverterError = newValue;

    if (newValue) {
      useRichText = false;
      showConverterError = true;
    }
  };

  /**
   * Convert the Markdown or HTML {@link inputValue} to Lexical nodes. Disable the rich text mode
   * and restore the original value when there is an error while conversion.
   */
  const convertToLexical = async () => {
    if (!editor || !initialized) {
      return;
    }

    const originalValue = inputValue;

    importCount += 1;

    const importId = importCount;

    importing = true;

    try {
      // We should avoid an empty editor; there should be at least one `<p>`, so give it an empty
      // string if the `value` is `undefined`
      // @see https://github.com/facebook/lexical/issues/2308
      const exported =
        config.format === 'html'
          ? await convertHtmlToLexical(editor, inputValue || '')
          : await convertMarkdownToLexical(editor, inputValue || '', enabledTransformers);

      // Skip an import superseded by a newer one, which sets its own value
      if (exported !== undefined) {
        lastImport = { source: originalValue, exported };
      }
    } catch (ex) {
      // Go through the setter, so the editor actually falls back to the plain text mode
      setConverterError(true);
      inputValue = originalValue;
      // eslint-disable-next-line no-console
      console.error(ex);
    } finally {
      // An earlier import finishing last doesn’t end the latest one
      if (importId === importCount) {
        importing = false;
      }
    }
  };

  return {
    /* eslint-disable jsdoc/require-jsdoc */
    get editor() {
      return editor;
    },
    set editor(newValue) {
      editor = newValue;
    },
    set enabledTransformers(newValue) {
      enabledTransformers = newValue;
    },
    get enabledTransformers() {
      return enabledTransformers;
    },
    get initialized() {
      return initialized;
    },
    set initialized(newValue) {
      initialized = newValue;
    },
    get config() {
      return config;
    },
    set config(newValue) {
      config = newValue;
      useRichText = newValue.modes[0] === 'rich-text' || newValue.isCodeEditor;
    },
    get inputValue() {
      return inputValue;
    },
    set inputValue(newValue) {
      const hasChange = inputValue !== newValue;

      if (hasChange) {
        inputValue = newValue;
      }

      if (useRichText && (hasChange || editor?.getEditorState().isEmpty())) {
        convertToLexical();
      }
    },
    get selection() {
      return selection;
    },
    set selection(newValue) {
      selection = newValue;
    },
    get controlId() {
      return useRichText ? `${editorId}-lexical-root` : `${editorId}-plain-text`;
    },
    get textArea() {
      return textArea;
    },
    set textArea(newValue) {
      textArea = newValue;
    },
    get useRichText() {
      return useRichText;
    },
    set useRichText(newValue) {
      useRichText = newValue;
    },
    get hasConverterError() {
      return hasConverterError;
    },
    set hasConverterError(newValue) {
      setConverterError(newValue);
    },
    get showConverterError() {
      return showConverterError;
    },
    set showConverterError(newValue) {
      showConverterError = newValue;
    },
    get pending() {
      return pending || runningOperations > 0;
    },
    set pending(newValue) {
      pending = newValue;
    },
    get importing() {
      return importing;
    },
    editorId,
    convertToLexical,
    /**
     * Mark an operation the user started as running, which makes the content count as
     * {@link TextEditorStore.pending} until it’s done. Use it for an operation that only reaches
     * the editor after an `await`, such as a language change waiting for the highlighter to load:
     * the flag the editor sets for itself is cleared by every update it makes in the meantime,
     * including the one the focus move fires, so it can’t cover the wait.
     * @returns {() => void} Function to call once the operation has updated the editor. Calling it
     * more than once has no further effect.
     */
    startOperation: () => {
      runningOperations += 1;

      let done = false;

      return () => {
        if (!done) {
          done = true;
          runningOperations -= 1;
        }
      };
    },
    /**
     * Get the value last imported if the given value, exported by the editor, is only that value
     * written in the editor’s own Markdown or HTML style.
     * @param {string} value Exported value.
     * @returns {string | undefined} Imported value, or `undefined` if the content has changed.
     */
    getImportedValue: (value) => (lastImport?.exported === value ? lastImport.source : undefined),
    /* eslint-enable jsdoc/require-jsdoc */
  };
};
