<script>
  import { _ } from '@sveltia/i18n';
  import { getContext } from 'svelte';
  import Icon from '../../icon/icon.svelte';
  import MenuButton from '../../menu/menu-button.svelte';
  import MenuItem from '../../menu/menu-item.svelte';
  import Menu from '../../menu/menu.svelte';
  import { insertEditorComponent } from './insert-component.js';

  /**
   * @import { TextEditorComponent, TextEditorStore } from '../../../typedefs.js';
   */

  /**
   * @typedef {object} Props
   * @property {TextEditorComponent[]} components Editor components.
   */

  /** @type {Props} */
  let {
    /* eslint-disable prefer-const */
    components,
    /* eslint-enable prefer-const */
  } = $props();

  /** @type {TextEditorStore} */
  const editorStore = getContext('editorStore');
</script>

<MenuButton label={_('_sui.insert')}>
  {#snippet endIcon()}
    <Icon name="arrow_drop_down" class="small-arrow" />
  {/snippet}
  {#snippet popup()}
    <Menu>
      {#each components as component (component.id)}
        {@const { label, icon } = component}
        <MenuItem
          {label}
          onclick={() => {
            insertEditorComponent(editorStore, component);
          }}
        >
          {#snippet startIcon()}
            {#if icon}
              <Icon name={icon} />
            {/if}
          {/snippet}
        </MenuItem>
      {/each}
    </Menu>
  {/snippet}
</MenuButton>
